async function commit(action,change,options={}){if(busy)return notice('Tunggu penyimpanan sebelumnya');const previous=structuredClone(data);busy=true;try{change();postChannelCosts(data);protectPeriods(previous,data);let approvalPin='';if(!options.approved&&data.settings.pinRequired){const sensitive=sensitiveChanges(previous,data);if(sensitive)approvalPin=await business.askPin()}if(session){$('#e-sync').textContent='Menyimpan…';const r=await api('state',{method:'PUT',body:JSON.stringify({revision,data,action,approvalPin})});revision=r.revision;const fresh=await api('state');data=normalizeData(fresh.data);revision=fresh.revision;}else data.audit.unshift({id:uid(),date:dateNow(),actor:'Demo',role:'Demo',action});render();if(lastDisplay?.orderId)publishDisplay(data.orders.find(o=>o.id===lastDisplay.orderId));notice(session?'Tersimpan di cloud':'Perubahan demo tersimpan selama halaman ini terbuka');return true}catch(e){data=previous;notice(e.message);throw e}finally{busy=false}}
async function refresh(){if(!session||busy||$('#enterpriseModal')?.classList.contains('active'))return;try{const r=await api('state');if(r.revision!==revision){data=normalizeData(r.data);revision=r.revision;await suite.cache();render()}$('#e-sync').textContent='Cloud aktif · Terakhir cek '+new Date().toLocaleTimeString('id-ID')}catch(e){$('#e-sync').textContent='Sinkron gagal: '+e.message}}
