function form(title,fields,onSave){const m=modal(title,`<form class="e-form">${fields.map(f=>`<label class="${f.type==='textarea'?'span2':''}">${f.label}${f.type==='select'?`<select name="${f.key}">${f.options.map(opt=>{const [v,l]=Array.isArray(opt)?opt:[opt,opt];return `<option value="${esc(v)}" ${String(f.value)===String(v)?'selected':''}>${esc(l)}</option>`}).join('')}</select>`:f.type==='textarea'?`<textarea name="${f.key}">${esc(f.value)}</textarea>`:`<input name="${f.key}" type="${f.type}" value="${f.type==='file'?'':esc(f.value)}" ${f.extra} ${['name','customer'].includes(f.key)?'required':''}>`}</label>`).join('')}<div class="e-form-error span2" role="alert"></div><footer><button class="outline-btn" type="button" data-cancel>Batal</button><button class="primary-btn" type="submit">Simpan</button></footer></form>`);m.querySelector('[data-cancel]').onclick=close;m.querySelector('form').onsubmit=async e=>{e.preventDefault();const button=m.querySelector('[type=submit]');button.disabled=true;m.querySelector('.e-form-error').textContent='';try{await onSave(Object.fromEntries(new FormData(e.target)),e.target);close()}catch(err){m.querySelector('.e-form-error').textContent=err.message}finally{button.disabled=false}};return m}
