function stockForm(waste=false){if(!data.inventory.length)return notice('Tambah bahan dulu');form(waste?'Catat waste':'Stok masuk / opname',[field('ingredient','Bahan','select',data.inventory[0].id,data.inventory.map(i=>[i.id,i.name+' ('+i.unit+')'])),bf(),field('type','Jenis','select',waste?'Kurangi':'Tambah',waste?['Kurangi']:['Tambah','Kurangi','Opname']),field('qty','Jumlah','number','',[],'min="0" step="0.001" required'),field('note','Alasan / supplier','textarea','')],v=>commit(waste?'Catat waste':'Perbarui stok',()=>{const i=data.inventory.find(i=>i.id===v.ingredient);const stock=Number(i.stocks[v.branch]||0);const qty=Number(v.qty);const delta=v.type==='Tambah'?qty:v.type==='Kurangi'?-qty:qty-stock;if(stock+delta<0)throw Error('Stok tidak cukup');adjustBatchStock(data,i.id,v.branch,delta);i.stocks[v.branch]=stock+delta;data.movements.push({id:uid(),date:today(),branch:v.branch,ingredientId:i.id,item:i.name,unit:i.unit,qty:delta,note:v.note||v.type});if(waste)data.expenses.push({id:uid(),date:today(),branch:v.branch,amount:qty*i.cost,category:'Waste',note:v.note,shift:''})}))}
