function confirmAction(text,fn){const m=modal('Konfirmasi',`<p>${esc(text)}</p><div class="e-actions"><button class="outline-btn" data-no>Batal</button><button class="primary-btn" data-yes>Lanjutkan</button></div><div class="e-form-error"></div>`);m.querySelector('[data-no]').onclick=close;m.querySelector('[data-yes]').onclick=async()=>{try{await fn();close()}catch(e){m.querySelector('.e-form-error').textContent=e.message}}}
function settingsForm(){const s=data.settings;form('Edit profil restoran',[field('name','Nama bisnis','text',s.name),field('ownerName','Nama pemilik tampilan','text',s.ownerName),field('phone','WhatsApp bisnis','tel',s.phone),field('address','Alamat','textarea',s.address),field('tax','Pajak (%)','number',s.tax,[],'min="0" max="100" required'),field('service','Layanan (%)','number',s.service,[],'min="0" max="100" required'),field('sampleData','Penanda data contoh','select',s.sampleData?'Tampilkan':'Sembunyikan',['Tampilkan','Sembunyikan']),field('logo','Logo (opsional)','file','',[],'accept="image/png,image/jpeg,image/webp"')],async v=>{let logo=s.logo;if(v.logo.size){if(v.logo.size>2097152||!['image/png','image/jpeg','image/webp'].includes(v.logo.type))throw Error('Logo PNG/JPG/WebP maksimal 2 MB');if(session){const r=await api('upload',{method:'POST',headers:{'content-type':v.logo.type},body:v.logo});logo=r.url}else logo=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(v.logo)})}await commit('Ubah profil bisnis',()=>{data.settings={...s,...v,tax:Number(v.tax),service:Number(v.service),sampleData:v.sampleData==='Tampilkan',logo}})})}
async function membersList(){if(!session)throw Error('Masuk dahulu');const members=await api('members');$('#member-list').innerHTML=table(['Email','Role','Aksi'],members.map(m=>[esc(m.email),esc(m.role),actions([['Cabut akses','member-remove',m.email,'danger']])]))+`<p class="e-code">Tautan tim: ${esc(location.origin+'/?workspace='+session.workspace)}</p>`;}
