function removeMember(email){return confirmAction('Cabut akses '+email+'?',async()=>{await api('members',{method:'DELETE',body:JSON.stringify({email})});await membersList()})}
async function onlineLink(){if(!session)throw Error('Masuk dahulu untuk mengaktifkan menu online');const url=location.origin+'/?online=1&workspace='+encodeURIComponent(session.workspace);const m=modal('QR menu pelanggan',`<canvas id="menuQR" class="e-qr"></canvas><p class="e-code">${esc(url)}</p><p><a href="${esc(url)}" target="_blank" rel="noopener">Buka menu pelanggan</a></p><button class="outline-btn" id="downloadQR">Unduh QR</button>`);await QRCode.toCanvas(m.querySelector('canvas'),url,{width:240,margin:2});m.querySelector('#downloadQR').onclick=()=>{const l=document.createElement('a');l.href=m.querySelector('canvas').toDataURL('image/png');l.download='qr-menu-ghifar-food.png';l.click()}}
let inbox=[];
async function onlineInbox(){if(!session)throw Error('Masuk dahulu untuk memuat inbox');inbox=await api('online-inbox');modal('Inbox pesanan online',table(['Pesanan','Pelanggan','Total','Aksi'],inbox.map(o=>[esc(o.number),esc(o.customer)+'<small>'+esc(o.phone)+'</small>',money(totalOf(o)),actions([['Terima pesanan','online-accept',o.id]])])))}
async function acceptOnline(id){const o=inbox.find(o=>o.id===id);if(!o)return;await commit('Terima pesanan online',()=>{if(!data.orders.some(x=>x.id===o.id))data.orders.push(o)});await api('online-inbox',{method:'POST',body:JSON.stringify({id})});await onlineInbox()}
function restoreForm(){form('Pulihkan backup (mengganti data ruang kerja)',[field('backup','File JSON backup Ghifar','file','',[],'accept="application/json" required')],async v=>{if(session&&session.role!=='Owner')throw Error('Hanya owner');const backup=JSON.parse(await v.backup.text());if(![1,2].includes(backup.schema)||!backup.data||!Array.isArray(backup.data.orders)||!Array.isArray(backup.data.branches))throw Error('Format backup tidak sesuai');const keys=Object.keys(initialData());if(keys.some(k=>!(k in backup.data)))throw Error('Backup tidak lengkap');if(!window.confirm('Ganti seluruh data dengan backup ini? Unduh backup terbaru dahulu.'))throw Error('Pemulihan dibatalkan');await commit('Pulihkan backup',()=>{const pinRequired=data.settings.pinRequired;data=normalizeData(backup.data);data.settings.pinRequired=pinRequired})})}
function xml(v){return String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g,'')}
function xlsx(name,sheets){const enc=new TextEncoder(),files=[];const put=(path,txt)=>files.push({path,bytes:enc.encode(txt)});const ns='http://schemas.openxmlformats.org/spreadsheetml/2006/main';put('[Content_Types].xml',`<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>${sheets.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}</Types>`);put('_rels/.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');put('xl/workbook.xml',`<?xml version="1.0"?><workbook xmlns="${ns}" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${sheets.map((s,i)=>`<sheet name="${xml(s.name)}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')}</sheets></workbook>`);put('xl/_rels/workbook.xml.rels',`<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${sheets.map((_,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')}</Relationships>`);sheets.forEach((s,i)=>put(`xl/worksheets/sheet${i+1}.xml`,`<?xml version="1.0"?><worksheet xmlns="${ns}"><sheetData>${s.rows.map((row,ri)=>`<row r="${ri+1}">${row.map((value,ci)=>{let col='',n=ci+1;while(n){n--;col=String.fromCharCode(65+n%26)+col;n=Math.floor(n/26)}const ref=col+(ri+1);return typeof value==='number'?`<c r="${ref}"><v>${Number.isFinite(value)?value:0}</v></c>`:`<c r="${ref}" t="inlineStr"><is><t xml:space="preserve">${xml(value)}</t></is></c>`}).join('')}</row>`).join('')}</sheetData></worksheet>`));download(name+'.xlsx',zip(files),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')}
function zip(files){const enc=new TextEncoder(),chunks=[],central=[];let offset=0;const le=(n,len)=>Array.from({length:len},(_,i)=>(n>>>i*8)&255);const crc=bytes=>{let c=-1;for(const b of bytes){c^=b;for(let k=0;k<8;k++)c=(c>>>1)^((c&1)?0xedb88320:0)}return (c^-1)>>>0};for(const f of files){const name=enc.encode(f.path),hash=crc(f.bytes),size=f.bytes.length;const h=new Uint8Array([...le(0x04034b50,4),...le(20,2),...le(0,2),...le(0,2),...le(0,2),...le(33,2),...le(hash,4),...le(size,4),...le(size,4),...le(name.length,2),...le(0,2),...name]);chunks.push(h,f.bytes);central.push(new Uint8Array([...le(0x02014b50,4),...le(20,2),...le(20,2),...le(0,2),...le(0,2),...le(0,2),...le(33,2),...le(hash,4),...le(size,4),...le(size,4),...le(name.length,2),...le(0,2),...le(0,2),...le(0,2),...le(0,2),...le(0,4),...le(offset,4),...name]));offset+=h.length+size}const cs=central.reduce((s,c)=>s+c.length,0);const end=new Uint8Array([...le(0x06054b50,4),...le(0,2),...le(0,2),...le(files.length,2),...le(files.length,2),...le(cs,4),...le(offset,4),...le(0,2)]);const all=[...chunks,...central,end],out=new Uint8Array(all.reduce((s,x)=>s+x.length,0));let pos=0;for(const c of all){out.set(c,pos);pos+=c.length}return out}
function exportOrders(orders){xlsx('penjualan-ghifar-'+today(),[{name:'Transaksi',rows:[['ID','Tanggal','Pelanggan','Cabang','Tipe','Status','Metode','Lunas','Subtotal','Diskon','Pajak','Layanan','Total'],...orders.map(o=>[o.number,o.date,o.customer,bname(o.branch),o.type,o.status,o.method,o.paid?'Ya':'Tidak',o.lines.reduce((s,l)=>s+l.qty*l.price,0),o.discount||0,o.tax||0,o.service||0,totalOf(o)])]},{name:'Item',rows:[['ID Pesanan','Menu','Jumlah','Harga','HPP per porsi','Total'],...orders.flatMap(o=>o.lines.map(l=>[o.number,l.name,l.qty,l.price,l.cost??'Belum diatur',l.qty*l.price]))]}]);notice('Excel .xlsx berhasil diunduh')}
function exportProfit(){const p=profitReport(data,ranged(data.orders),ranged(data.expenses));xlsx('laba-rugi-ghifar-'+from+'-'+until,[{name:'Laba Rugi',rows:[['Laporan Ghifar Food',from,until],['Komponen','Nominal'],['Penjualan bersih',p.net],['HPP',p.hpp],['Laba kotor',p.gross],['Biaya operasional',p.spending],['Laba operasional',p.profit],['Pajak dipungut',p.tax],['Layanan dipungut',p.service],['Status modal',p.unknown?'Belum lengkap':'Lengkap']]},{name:'Biaya',rows:[['Tanggal','Cabang','Kategori','Catatan','Nominal'],...ranged(data.expenses).map(e=>[e.date,bname(e.branch),e.category,e.note,e.amount])]}]);notice('Laporan laba-rugi Excel diunduh')}
async function startOnline(){updateMenuTab('online');document.querySelector('.app-shell').style.display='none';let catalog;try{catalog=await api('public-menu')}catch(e){document.body.insertAdjacentHTML('beforeend','<main class="online-store"><h1>Menu pelanggan</h1><p>'+esc(e.message)+'</p></main>');return}let cart=[],onlineBranch=catalog.branches[0]?.id;const main=document.createElement('main');main.className='online-store';document.body.append(main);
const draw=()=>{main.innerHTML='<h1>'+esc(catalog.settings.name)+'</h1><p>Pilih menu, varian, dan topping. Pajak/layanan ditambahkan saat kirim. Pembayaran dikonfirmasi restoran.</p><label>Cabang<select id="onlineBranch">'+catalog.branches.map(b=>'<option value="'+b.id+'" '+(b.id===onlineBranch?'selected':'')+'>'+esc(b.name)+'</option>').join('')+'</select></label><div class="e-cards">'+catalog.menus.map(m=>'<article class="e-card">'+(m.photo?'<img src="'+esc(m.photo)+'" alt="'+esc(m.name)+'">':'<div class="e-card-photo">🍽️</div>')+'<h3>'+esc(m.name)+'</h3><b>'+money(m.price)+'</b><p><button class="e-button" '+(m.availability?.[onlineBranch]?.available===false?'disabled':'')+' data-online-add="'+m.id+'">'+(m.availability?.[onlineBranch]?.available===false?'Habis':'Pilih menu')+'</button></p></article>').join('')+'</div><section class="panel"><h2>Keranjang</h2>'+cart.map(l=>'<div class="pos-line"><span>'+esc(l.name)+'<small>'+esc(l.note)+'</small></span><input type="number" min="1" max="30" value="'+l.qty+'" data-online-qty="'+l.id+'"><button data-online-remove="'+l.id+'">×</button></div>').join('')+'<div class="online-order-footer"><strong>Subtotal '+money(cart.reduce((s,l)=>s+l.qty*l.price,0))+'</strong><button class="primary-btn" id="checkoutOnline">Pesan</button></div></section>';
main.querySelector('#checkoutOnline').onclick=()=>{if(!cart.length)return notice('Pilih menu dahulu');form('Kirim pesanan',[field('customer','Nama pelanggan','text',''),field('phone','WhatsApp','tel','',[],'required'),field('branch','Cabang','select',onlineBranch,catalog.branches.map(b=>[b.id,b.name])),field('note','Catatan','textarea','')],async v=>{const r=await api('online-order',{method:'POST',body:JSON.stringify({...v,workspace,website:'',lines:cart.map(l=>({menuId:l.menuId,qty:l.qty,variantId:l.variantId,addonIds:l.addonIds,comboSelections:l.comboSelections,note:l.note}))})});cart=[];draw();setTimeout(()=>{const phone=String(catalog.settings.phone||'').replace(/[^0-9]/g,'').replace(/^0/,'62');modal('Pesanan diterima · '+esc(r.number),'<p>Pesanan masuk ke inbox kasir. Total '+money(r.total)+'. Pembayaran dan waktu siap dikonfirmasi restoran.</p><a class="growth-link" target="_blank" rel="noopener" href="'+esc(location.origin+'/?track='+r.token+'&workspace='+encodeURIComponent(workspace))+'">Lacak pesanan & beri ulasan</a>'+(phone?'<a href="https://wa.me/'+phone+'?text='+encodeURIComponent('Halo, konfirmasi '+r.number+' atas nama '+v.customer)+'" target="_blank" rel="noopener">Konfirmasi melalui WhatsApp</a>':''))},0)})}};
draw();main.addEventListener('click',e=>{const add=e.target.closest('[data-online-add]');if(add){const m=catalog.menus.find(m=>m.id===add.dataset.onlineAdd),fields=[field('variantId','Varian','select','',[['','Standar'],...m.variants.map(v=>[v.id,v.name+' + '+money(v.extra)])]),field('qty','Jumlah','number',1,[],'min="1" max="30" required'),field('note','Catatan / level pedas','text','')];m.combo?.groups.forEach(g=>fields.push(field('combo-'+g.id,g.name,'select','',g.options.filter(id=>catalog.menus.some(m=>m.id===id&&m.availability?.[onlineBranch]?.available!==false)).map(id=>{const x=catalog.menus.find(m=>m.id===id);return [id,x.name]}))));m.addons.forEach(a=>fields.push(field('addon-'+a.id,esc(a.name)+' + '+money(a.extra),'select','Tidak',['Tidak','Ya'])));form('Pilih '+esc(m.name),fields,v=>{const variant=m.variants.find(a=>a.id===v.variantId),addons=m.addons.filter(a=>v['addon-'+a.id]==='Ya');const comboSelections=Object.fromEntries((m.combo?.groups||[]).map(g=>[g.id,v['combo-'+g.id]]));cart.push({comboSelections,id:uid(),menuId:m.id,variantId:v.variantId,addonIds:addons.map(a=>a.id),name:m.name+(m.combo?' · '+Object.values(comboSelections).map(id=>catalog.menus.find(m=>m.id===id)?.name).join(' + '):'')+(variant?' · '+variant.name:'')+(addons.length?' + '+addons.map(a=>a.name).join(', '):''),price:m.price+Number(variant?.extra||0)+addons.reduce((s,a)=>s+Number(a.extra),0),qty:Number(v.qty),note:v.note});draw()})}const remove=e.target.closest('[data-online-remove]');if(remove){cart=cart.filter(l=>l.id!==remove.dataset.onlineRemove);draw()}});
setInterval(async()=>{if($('#enterpriseModal')?.classList.contains('active'))return;try{catalog=await api('public-menu');draw()}catch{}},10000);main.addEventListener('change',e=>{if(e.target.id==='onlineBranch'){onlineBranch=e.target.value;draw()}if(e.target.dataset.onlineQty){cart.find(l=>l.id===e.target.dataset.onlineQty).qty=Math.min(30,Math.max(1,Number(e.target.value)||1));draw()}})}

async function start(){const params=new URLSearchParams(location.search);if(params.has('track')||params.has('display'))return startPublicScreen({api,esc,money,workspace,kind:params.has('track')?'tracking':'display',token:params.get('track')});if(params.has('online'))return startOnline();try{session=await api('session');const r=await api('state');data=normalizeData(r.data);revision=r.revision;if(session.role==='Kitchen')view='kitchen';if(session.role==='Pelayan')view='waiter'}catch(e){session=null;if(!navigator.onLine){const saved=await suite.cachedSession().catch(()=>null);if(saved){session=saved.session;data=normalizeData(saved.data);revision=saved.revision;view=session.role==='Pelayan'?'waiter':session.role==='Kitchen'?'kitchen':'orders';notice('Mode offline · akun terakhir di perangkat ini')}else notice('Belum ada cache. Aktifkan Offline & perangkat ketika online.')}else notice(e.message.includes('Silakan')?'Mode demo · Masuk untuk menyimpan cloud':e.message)}render();await suite.init();setInterval(async()=>{await suite.flush().catch(e=>console.warn(e.message));await refresh();if(['kitchen','reservations','alerts','waiter','availability','tracking','receivables','budgets'].includes(view)&&!$('#enterpriseModal')?.classList.contains('active'))render()},10000);window.addEventListener('afterprint',()=>document.body.classList.remove('e-printing'))}
async function orderAdvance(id,status){if(!session)return commit('Pesanan → '+status,()=>{const o=data.orders.find(o=>o.id===id);advanceOrder(data,id,status);if(status==='Dibatalkan'&&o.pointsRedeemed&&!o.pointsReturned){const c=data.customers.find(c=>c.id===o.customerId);if(c)c.points+=o.pointsRedeemed;o.pointsReturned=true}});if(busy)throw Error('Tunggu penyimpanan sebelumnya');busy=true;try{await api('order-action',{method:'POST',body:JSON.stringify({id,status,revision})});const fresh=await api('state');data=normalizeData(fresh.data);revision=fresh.revision;await suite.cache();render();notice('Status, stok, dan poin tersimpan di cloud')}finally{busy=false}}
function supplierForm(id){const s=data.suppliers.find(s=>s.id===id)||{};crud('suppliers',id?'Edit supplier':'Tambah supplier',[field('name','Nama supplier','text',s.name),field('phone','Telepon / WhatsApp','tel',s.phone),field('email','Email (opsional)','email',s.email),field('category','Kategori bahan','text',s.category),field('address','Alamat','textarea',s.address)],id)}
function purchaseForm(){if(!data.suppliers.length||!data.inventory.length)return notice('Tambahkan supplier dan bahan terlebih dahulu');form('Pesanan pembelian bahan',[field('supplier','Supplier','select','',data.suppliers.map(s=>[s.id,s.name])),field('ingredient','Bahan','select','',data.inventory.map(i=>[i.id,i.name+' ('+i.unit+')'])),bf(),field('qty','Jumlah','number','',[],'min="0.001" step="0.001" required'),field('cost','Harga beli per satuan','number','',[],'min="0" required'),field('due','Tanggal rencana datang','date',today(),[],'required'),field('expiry','Kedaluwarsa (opsional)','date',''),field('invoiceNumber','Nomor invoice (opsional)','text',''),field('paymentDue','Jatuh tempo pembayaran','date',today(),[],'required'),field('note','Catatan','textarea','')],v=>commit('Buat pembelian bahan',()=>{const id=uid();data.purchases.push({...v,id,number:'PO-'+id.slice(0,8).toUpperCase(),qty:Number(v.qty),cost:Number(v.cost),date:today(),status:'Dipesan'})}))}
function receivePurchase(id){const p=data.purchases.find(p=>p.id===id);if(!p||p.status!=='Dipesan')throw Error('Pembelian sudah diproses');const i=data.inventory.find(i=>i.id===p.ingredient);if(!i)throw Error('Bahan tidak ditemukan');const old=Number(i.stocks[p.branch]||0);const all=data.branches.reduce((s,b)=>s+Number(i.stocks[b.id]||0),0);i.cost=(all*i.cost+p.qty*p.cost)/Math.max(all+p.qty,0.001);i.stocks[p.branch]=old+p.qty;p.status='Diterima';p.received=dateNow();addBatch(data,{ingredient:i.id,branch:p.branch,qty:p.qty,cost:p.cost,received:today(),expiry:p.expiry||'',code:p.number,addStock:false});const invoice={id:uid(),number:p.invoiceNumber||'INV-'+p.number,supplier:p.supplier,branch:p.branch,date:today(),due:p.paymentDue||today(),total:p.qty*p.cost,purchaseId:p.id,payments:[],note:p.note||''};data.supplierInvoices.push(invoice);p.invoiceId=invoice.id;data.movements.push({id:uid(),date:today(),branch:p.branch,ingredientId:i.id,item:i.name,unit:i.unit,qty:p.qty,note:'Penerimaan '+p.number});notice('Stok bertambah. Pembelian persediaan tidak dihitung ulang sebagai biaya HPP.');}
function exportStock(){xlsx('inventori-ghifar-'+today(),[{name:'Stok',rows:[['Bahan','Satuan','Cabang','Stok','Minimum','Modal'],...data.inventory.flatMap(i=>data.branches.filter(b=>branch==='all'||b.id===branch).map(b=>[i.name,i.unit,b.name,Number(i.stocks[b.id]||0),i.min,i.cost]))]},{name:'Mutasi',rows:[['Tanggal','Cabang','Bahan','Jumlah','Satuan','Catatan'],...selected(data.movements).map(m=>[m.date,bname(m.branch),m.item,m.qty,m.unit,m.note])]}])}
function exportStaff(){xlsx('karyawan-ghifar-'+today(),[{name:'Karyawan',rows:[['Nama','Jabatan','Cabang','Email','Telepon','Masuk','Pulang','Gaji','Status'],...selected(data.employees).map(e=>[e.name,e.role,bname(e.branch),e.email,e.phone,e.start,e.end,e.salary,e.active?'Aktif':'Nonaktif'])]},{name:'Absensi',rows:[['Tanggal','Karyawan','Masuk','Pulang','Telat (menit)'],...ranged(data.attendance).map(a=>[a.date,data.employees.find(e=>e.id===a.employee)?.name,a.in,a.out,a.late])]}])}
async function importLegacy(){const read=k=>{try{return JSON.parse(localStorage.getItem(k)||'null')}catch{return null}};const employees=read('ghifarFoodEmployees')||[],menus=read('ghifarFoodMenus')||[];const profile=read('ghifarFoodBusinessProfile')||{},owner=read('ghifarFoodOwner')||{};if(!employees.length&&!menus.length&&!Object.keys(profile).length&&!Object.keys(owner).length)return notice('Tidak ditemukan data profil, menu, atau karyawan lama di browser ini. Backup lama tetap bisa diunduh.');confirmAction('Impor profil, menu dan karyawan dari browser ini? Transaksi lama tetap di backup; tidak diimpor karena format lama tidak memiliki rincian item/HPP yang lengkap.',()=>commit('Impor data browser lama',()=>{if(profile.businessName)data.settings.name=profile.businessName;if(profile.businessPhone)data.settings.phone=profile.businessPhone;if(profile.businessAddress)data.settings.address=profile.businessAddress;if(owner.name)data.settings.ownerName=owner.name;for(const e of employees){if(data.employees.some(x=>x.id===e.id))continue;const hours=String(e.hours||'08:00–16:00').split(/[–-]/);data.employees.push({...e,branch:data.branches[0].id,start:hours[0]||'08:00',end:hours[1]||'16:00',salary:Number(e.salary||0)})}for(const m of menus){if(data.menus.some(x=>x.id===m.id))continue;data.menus.push({id:m.id||uid(),name:m.name,price:Number(m.price||0),category:m.category||'Makanan',photo:m.photo||'',available:m.available!==false})}}))}
function updateAlerts(){let bell=$('#notificationBell');if(!bell){bell=document.createElement('button');bell.id='notificationBell';bell.className='notification-button';bell.dataset.eView='alerts';$('.top-actions')?.prepend(bell)}const list=alertsFor(data).filter(a=>!data.notificationReads.some(r=>r.id===a.id&&r.actor===(session?.email||'Demo')));bell.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M5 17h14l-2-4V9a5 5 0 0 0-10 0v4ZM10 21h4"/></svg><b>'+list.length+'</b>';bell.setAttribute('aria-label','Notifikasi · '+list.length+' belum dibaca')}
